B.bNJ=s(["Pri enskripsyon, premye pery\xf2d ladan l","Inscription, premi\xe8re p\xe9riode incluse","Registration, first period included"],t.s)
B.bx8=s(["Pri total premye enskripsyon an. Kite vid pou itilize pri renouv\xe8lman an.","Prix total de la premi\xe8re inscription. Vide : m\xeame prix que le renouvellement.","Total first registration price. Leave blank to use the renewal price."],t.s)
B.bLP=s(["Im\xe8l obligatwa pou resevwa konfimasyon enskripsyon ak renouv\xe8lman yo.","Email requis pour recevoir les confirmations d\u2019inscription et de renouvellement.","Email required for registration and renewal confirmations."],t.s)
B.bKt=s(["Manm ki te deja la","Membre d\xe9j\xe0 inscrit \xe0 la salle","Existing gym member"],t.s)
B.bpi=s(["Reprann yon manm nan ansyen kaye a, san fr\xe8 enskripsyon.","Reprise du registre existant, sans frais d\u2019inscription.","Import from the existing register, without registration fees."],t.s)
B.b5T=s(["Chwazi pery\xf2d li te deja peye a","Choisir la p\xe9riode d\xe9j\xe0 r\xe9gl\xe9e","Choose the previously paid period"],t.s)
B.bjQ=s(["Pery\xf2d sa a deja peye. Pa gen nouvo lajan k ap antre nan k\xe8s la.","P\xe9riode d\xe9j\xe0 r\xe9gl\xe9e : aucun nouvel encaissement dans la caisse.","Already paid: no new cash receipt will be recorded."],t.s)
B.bcn=s(["Pery\xf2d reprann nan kaye a","P\xe9riode reprise du registre","Period imported from register"],t.s)
B.bnL=s(["Swivi im\xe8l yo","Suivi des emails","Email status"],t.s)
B.bMd=s(["Limit pataje / 24 \xe8dtan","Limite partag\xe9e / 24 heures","Shared limit / 24 hours"],t.s)
B.bqv=s(["An atant","En attente","Queued"],t.s)
B.bov=s(["Ap voye","En cours","Sending"],t.s)
B.bJT=s(["Voye","Envoy\xe9s","Sent"],t.s)
